// Custom @FunctionalInterface with default composition + static factories
package com.bank.validation.function;

import com.bank.validation.model.Trade;
import java.math.BigDecimal;

@FunctionalInterface
public interface TradeValidator {

    // ═══ THE ONE ABSTRACT METHOD (SAM) — lambdas implement THIS ═══
    boolean validate(Trade trade);

    // ═══ DEFAULT METHODS: composition — do NOT count as abstract ═══

    default TradeValidator and(TradeValidator other) {
        return trade -> this.validate(trade) && other.validate(trade);
    }

    default TradeValidator or(TradeValidator other) {
        return trade -> this.validate(trade) || other.validate(trade);
    }

    default TradeValidator negate() {
        return trade -> !this.validate(trade);
    }

    // ═══ STATIC FACTORY METHODS: common validators — do NOT count as abstract ═══

    static TradeValidator hasAccountId() {
        return trade -> trade.getAccountId() != null && !trade.getAccountId().isBlank();
    }

    static TradeValidator hasSymbol() {
        return trade -> trade.getSymbol() != null && !trade.getSymbol().isBlank();
    }

    static TradeValidator hasPositiveQuantity() {
        return trade -> trade.getQuantity() > 0;
    }

    static TradeValidator maxAmount(BigDecimal max) {
        return trade -> trade.getAmount().compareTo(max) <= 0;
    }

    static TradeValidator validSide() {
        return trade -> "BUY".equals(trade.getSide()) || "SELL".equals(trade.getSide());
    }

    // ═══ ALWAYS PASS / ALWAYS FAIL ═══
    static TradeValidator always() { return trade -> true; }
    static TradeValidator never() { return trade -> false; }
}
