package com.bank.validation.service;

import com.bank.validation.dto.ValidationResult;
import com.bank.validation.function.TradeValidator;
import com.bank.validation.model.Trade;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class ValidationEngine {

    private final EntityManager em;

    @Value("${validation.max-amount:10000000}")
    private BigDecimal maxAmount;

    @Transactional(readOnly = true)
    public ValidationResult validateTrade(String tradeId) {
        Trade trade = em.find(Trade.class, tradeId);
        if (trade == null) throw new IllegalArgumentException("Trade not found: " + tradeId);

        // ═══ COMPOSE validators using and() — all must pass ═══
        TradeValidator composedRule = TradeValidator.hasAccountId()
            .and(TradeValidator.hasSymbol())
            .and(TradeValidator.hasPositiveQuantity())
            .and(TradeValidator.validSide())
            .and(TradeValidator.maxAmount(maxAmount));

        boolean valid = composedRule.validate(trade);

        // ═══ Check individual rules for detailed error messages ═══
        List<String> failures = new ArrayList<>();
        Map<String, TradeValidator> rules = new LinkedHashMap<>();
        rules.put("accountId required", TradeValidator.hasAccountId());
        rules.put("symbol required", TradeValidator.hasSymbol());
        rules.put("quantity > 0", TradeValidator.hasPositiveQuantity());
        rules.put("side must be BUY or SELL", TradeValidator.validSide());
        rules.put("amount <= " + maxAmount, TradeValidator.maxAmount(maxAmount));

        rules.forEach((name, validator) -> {
            if (!validator.validate(trade)) failures.add(name);
        });

        // ═══ Demonstrate ALL core functional interfaces ═══
        // Predicate<Trade>: filtering
        Predicate<Trade> isValid = composedRule::validate;  // method ref to our custom FI!

        // Function<Trade, BigDecimal>: transformation
        Function<Trade, BigDecimal> toAmount = Trade::getAmount;

        // Consumer<Trade>: side effect
        Consumer<Trade> logResult = t ->
            log.info("Validated {}: {} (failures: {})", t.getTradeId(), valid ? "PASS" : "FAIL", failures);
        logResult.accept(trade);

        // Supplier<String>: lazy factory
        Supplier<String> ruleDescription = () -> "accountId + symbol + qty>0 + validSide + maxAmount";

        // UnaryOperator<BigDecimal>: same-type transform
        UnaryOperator<BigDecimal> applyTax = amount -> amount.multiply(new BigDecimal("0.9")); // 10% tax

        // BinaryOperator<BigDecimal>: reduce two values
        BinaryOperator<BigDecimal> sum = BigDecimal::add;

        return new ValidationResult(tradeId, valid, failures, ruleDescription.get());
    }
}
