package com.bank.validation.function;

import com.bank.validation.model.Trade;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class TradeValidatorTest {

    @Test
    void shouldValidateWithStaticFactory() {
        Trade validTrade = mock(Trade.class);
        when(validTrade.getAccountId()).thenReturn("SAV2001");
        when(validTrade.getSymbol()).thenReturn("RELIANCE");
        when(validTrade.getQuantity()).thenReturn(100);
        when(validTrade.getSide()).thenReturn("BUY");
        when(validTrade.getAmount()).thenReturn(new BigDecimal("245050"));

        assertThat(TradeValidator.hasAccountId().validate(validTrade)).isTrue();
        assertThat(TradeValidator.hasSymbol().validate(validTrade)).isTrue();
        assertThat(TradeValidator.hasPositiveQuantity().validate(validTrade)).isTrue();
    }

    @Test
    void shouldComposeWithAnd() {
        Trade invalidTrade = mock(Trade.class);
        when(invalidTrade.getAccountId()).thenReturn("");  // BLANK!
        when(invalidTrade.getSymbol()).thenReturn("RELIANCE");
        when(invalidTrade.getQuantity()).thenReturn(100);

        TradeValidator composed = TradeValidator.hasAccountId()
            .and(TradeValidator.hasSymbol())
            .and(TradeValidator.hasPositiveQuantity());

        assertThat(composed.validate(invalidTrade)).isFalse();  // accountId fails → whole fails
    }

    @Test
    void shouldNegate() {
        Trade activeTrade = mock(Trade.class);
        when(activeTrade.getAccountId()).thenReturn("SAV2001");

        TradeValidator hasAccount = TradeValidator.hasAccountId();
        TradeValidator noAccount = hasAccount.negate();

        assertThat(hasAccount.validate(activeTrade)).isTrue();
        assertThat(noAccount.validate(activeTrade)).isFalse();  // negated!
    }

    @Test
    void shouldComposeWithOr() {
        Trade tradeWithAccount = mock(Trade.class);
        when(tradeWithAccount.getAccountId()).thenReturn("SAV2001");
        when(tradeWithAccount.getSymbol()).thenReturn("");  // no symbol

        TradeValidator accountOrSymbol = TradeValidator.hasAccountId()
            .or(TradeValidator.hasSymbol());

        assertThat(accountOrSymbol.validate(tradeWithAccount)).isTrue();  // account passes → OR passes
    }
}
