    @InjectMocks ValidationEngine engine;

    @Test
    void shouldPassValidTrade() {
        Trade trade = mock(Trade.class);
        when(trade.getTradeId()).thenReturn("TRD-001");
        when(trade.getAccountId()).thenReturn("SAV2001");
        when(trade.getSymbol()).thenReturn("RELIANCE");
        when(trade.getQuantity()).thenReturn(100);
